package com.production.maintenance.model;
import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; import java.time.LocalDate;
@Entity @Table(name="machines") public class Machine { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Column(nullable=false,unique=true) private String code; @NotBlank @Column(nullable=false) private String name; private String type; private String location; private String status="RUNNING"; private LocalDate installationDate; private String notes; public Machine(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getInstallationDate(){return installationDate;} public void setInstallationDate(LocalDate v){installationDate=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }
